#include <stdio.h>
#include <stdlib.h>

void make_out(int *out) { *out = 7; }        /* 姿势①：调用者给存储，函数写出参 */

int *make_heap(void) {                        /* 姿势②：返回堆内存，调用者负责 free */
    int *p = (int *)malloc(sizeof(int));
    if (p != NULL) *p = 7;
    return p;
}

int main(void) {
    int value = 0;
    make_out(&value);
    printf("出参方式 value = %d\n", value);

    int *hp = make_heap();
    if (hp != NULL) {
        printf("堆方式 *hp = %d\n", *hp);
        free(hp);
        hp = NULL;
    }
    return 0;
}

