int main(void) {
    int *p = (int *)malloc(sizeof(int));
    if (p == NULL) return 1;
    *p = 99;
    printf("free 之前 *p = %d\n", *p);

    free(p);
    p = NULL;                   /* 释放后立刻置空，指针不再有"看起来能用"的地址 */

    if (p != NULL) {
        *p = 100;               /* 判空后这行自然被跳过 */
        printf("不会走到这里\n");
    } else {
        printf("p 已置空，写操作被安全拦下\n");
    }
    free(p);                    /* free(NULL) 是合法空操作，不会二次释放 */
    printf("程序正常结束，退出码 0\n");
    return 0;
}

