#include <stdio.h>
#include <stdlib.h>

int main(void) {
    long total = 0;
    for (int i = 0; i < 1000; i++) {
        int *p = (int *)malloc(1024 * sizeof(int));
        if (p == NULL) {
            printf("第 %d 次分配失败\n", i);
            break;                       /* 失败也要保证已分配的都被释放了 */
        }
        p[0] = i;
        total += (long)(1024 * sizeof(int));
        free(p);                         /* 用完立刻还：常驻内存不随轮次增长 */
        p = NULL;
    }
    printf("累计申请并归还 %ld 字节，峰值占用只有一轮的 4 KB\n", total);
